/**
 * Document identity: the browser tab, the bookmark and the history entry.
 *
 * A visitor who opens a sheet, searches for a place or narrows the list to a
 * collection gets a `document.title` that says what they are looking at instead
 * of the generic product title. The browser reuses that string for the tab, for
 * “add bookmark” and for the entries in the back/forward menu — so “back” reads
 * “Das Zürychgow (1547) · Kartenzeit” instead of five identical “Kartenzeit”
 * steps. The `<meta name="description">` follows the same subject, so a
 * JavaScript-rendering crawler or an accessibility tool sees the same facts as
 * the visible page.
 *
 * Rules (in this order, and deliberately no further):
 *   1. a selected record names itself — with its publication years, and with
 *      “Blatt n von m” when the open work really has several sheets (only from
 *      the second sheet on: sheet 1 is the work's default view);
 *   2. otherwise the search subject: the typed query, else the chosen place;
 *   3. otherwise a collection filter (“Sammlung …”);
 *   4. otherwise the product's own title and description from `index.html`,
 *      which stay the single source of truth for the wording.
 *
 * Year range, provider and type filters do not reach the title on purpose: they
 * are visible above the list and in the URL, and every extra clause makes the
 * tab unreadable. Nothing here is derived from anything but the record data.
 *
 * The module only reads the store and writes to `document`, so it cannot touch
 * the URL contract (D6) and a failing module changes nothing else (D4).
 */

import { formatYearRange } from './dom.js';

/** Used when `index.html` does not carry a title (never observed, but safe). */
export const BASE_TITLE = 'Kartenzeit – Historische Karten entdecken';

/** German UI style: one space between number and unit, no thousands separator. */
const QUERY_MAX = 48;
const TITLE_MAX = 72;
const COLLECTION_MAX = 60;

/** Collapse whitespace and cut at a word boundary — a title is one line. */
export function shortenText(value, max) {
  const text = String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
  if (!text) return '';
  if (text.length <= max) return text;
  const cut = text.slice(0, max - 1);
  const space = cut.lastIndexOf(' ');
  return `${(space > max * 0.5 ? cut.slice(0, space) : cut).trimEnd()}…`;
}

/** “4 Karten” / “1 Karte” / “” when the count is not known yet. */
function countLabel(count) {
  if (!Number.isFinite(count)) return '';
  return `${count} ${count === 1 ? 'Karte' : 'Karten'}`;
}

/**
 * The document title and description for a state — pure, so it is unit-tested
 * without a browser.
 *
 * @param {object} state store state (`q`, `place`, `collection`, `selected`, `sheet`)
 * @param {object} [context]
 * @param {object|null} [context.record] the selected record, if any
 * @param {number|null} [context.count] size of the current result list, if known
 * @param {string} [context.base] product title to fall back to
 * @param {string} [context.baseDescription] product description to fall back to
 * @returns {{title: string, description: string}}
 */
export function describeDocument(state = {}, { record = null, count = null, base = BASE_TITLE, baseDescription = '' } = {}) {
  const productTitle = String(base ?? '').trim() || BASE_TITLE;
  const brand = ` · Kartenzeit`;
  const cards = countLabel(count);
  const sheetState = Math.floor(Number(state?.sheet));

  if (record) {
    const years = formatYearRange(record.yearStart, record.yearEnd ?? record.yearStart);
    const label = `${shortenText(record.title, TITLE_MAX)}${years ? ` (${years})` : ''}`;
    const total = Math.floor(Number(record.canvasCount));
    const sheet = sheetState > 1 && total > 1 ? ` · Blatt ${Math.min(sheetState, total)} von ${total}` : '';
    return {
      title: `${label}${sheet}${brand}`,
      description:
        `${label}${record.institution ? ` – ${record.institution}` : ''}. ` +
        'IIIF-Vorschau, Rechtehinweis und Link zum Originaldatensatz in Kartenzeit.',
    };
  }

  const subject = shortenText(state?.q, QUERY_MAX) || shortenText(state?.place, QUERY_MAX);
  if (subject) {
    return {
      title: `„${subject}“${cards ? ` · ${cards}` : ''}${brand}`,
      description: `${cards ? `${cards}: ` : ''}Historische Karten zu „${subject}“ auf der Karte suchen, nach Zeitraum und Sammlung filtern und zum Originaldatensatz springen.`,
    };
  }

  const collection = shortenText(state?.collection, COLLECTION_MAX);
  if (collection) {
    return {
      title: `Sammlung „${collection}“${cards ? ` · ${cards}` : ''}${brand}`,
      description: `${cards ? `${cards} aus ` : 'Historische Karten aus '}der Sammlung „${collection}“: auf der Karte suchen, nach Zeitraum filtern und zum Originaldatensatz springen.`,
    };
  }

  return { title: productTitle, description: String(baseDescription ?? '') };
}

/**
 * Wire the document identity to the store and the filter bus.
 *
 * The base title/description are read from the page itself, so `index.html`
 * keeps owning that wording. `count` arrives with `records:filtered` (the list
 * is the only place that knows the size of the current result set); until then
 * the count is simply left out of the title.
 */
export function init(ctx) {
  const base = document.title || BASE_TITLE;
  const meta = document.querySelector('meta[name="description"]');
  const baseDescription = meta?.getAttribute('content') ?? '';
  let count = null;
  let applied = null;

  function apply() {
    const state = ctx.store.getState();
    const record = state.selected ? (ctx.data.recordIndex?.get(state.selected) ?? null) : null;
    const next = describeDocument(state, { record, count, base, baseDescription });
    if (next.title !== applied?.title) document.title = next.title;
    if (meta && next.description && meta.getAttribute('content') !== next.description) {
      meta.setAttribute('content', next.description);
    }
    applied = next;
    return next;
  }

  ctx.store.subscribe(() => {
    apply();
  });
  ctx.bus.on('records:filtered', ({ records } = {}) => {
    count = Array.isArray(records) ? records.length : null;
    apply();
  });
  apply();

  // Small API for the browser check and for a future “share” control: it is the
  // only way to ask the module what it currently shows.
  return { apply, describeDocument };
}

