/**
 * Document identity (tab / bookmark / history entry).
 *
 * The rules are pure functions of the store state plus the record data, so they
 * are verified here without a browser; `scripts/browser-check.mjs` then asserts
 * that the wired module really writes them into a live `document.title`, that a
 * `?sel=` deep link names the sheet on load and that closing the panel restores
 * the product title.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { BASE_TITLE, describeDocument, shortenText } from '../public/app/title.js';

const root = fileURLToPath(new URL('..', import.meta.url));
const records = JSON.parse(await readFile(path.join(root, 'public/data/records.json'), 'utf8')).records;
const recordOf = (id) => records.find((r) => r.id === id);

const BASE_DESCRIPTION = 'Historische Karten und Atlanten auf einer interaktiven Weltkarte entdecken.';

test('the untouched start state keeps the product title and description verbatim', () => {
  const { title, description } = describeDocument({}, { base: BASE_TITLE, baseDescription: BASE_DESCRIPTION });
  assert.equal(title, BASE_TITLE);
  assert.equal(description, BASE_DESCRIPTION);
});

test('an opened record names itself with its publication years', () => {
  const record = recordOf('e-rara:8562848');
  assert.ok(record, 'the seed still carries the record used by the browser check');
  const { title, description } = describeDocument({ selected: record.id }, { record, base: BASE_TITLE });
  assert.equal(title, 'Das Zürychgow (1547) · Kartenzeit');
  assert.match(description, /Das Zürychgow \(1547\) – Zentralbibliothek Zürich\./);
  assert.match(description, /Originaldatensatz/);
});

test('a record without years does not leave an empty pair of brackets', () => {
  const record = { id: 'x:1', title: 'Ohne Jahr', yearStart: null, yearEnd: null, institution: 'ZB' };
  const { title, description } = describeDocument({ selected: record.id }, { record });
  assert.equal(title, 'Ohne Jahr · Kartenzeit');
  assert.ok(!title.includes('()'));
  assert.ok(!description.includes('()'));
  assert.ok(!/\s{2}/.test(description));
});

test('only a later sheet of a real multi-sheet work is named in the title', () => {
  const canton = recordOf('e-rara:8935807');
  assert.ok((canton.canvasCount ?? 0) > 1, 'the seed still carries a multi-sheet work');
  assert.equal(
    describeDocument({ selected: canton.id, sheet: 12 }, { record: canton }).title.endsWith(' · Blatt 12 von 35 · Kartenzeit'),
    true,
  );
  // Sheet 1 is the work's default view: no clause. A sheet beyond the real range
  // is clamped instead of naming a sheet that does not exist.
  assert.ok(!describeDocument({ selected: canton.id, sheet: 1 }, { record: canton }).title.includes('Blatt'));
  assert.ok(describeDocument({ selected: canton.id, sheet: 99 }, { record: canton }).title.includes('Blatt 35 von 35'));
  // A single-sheet record never carries the clause, whatever the URL says.
  const single = recordOf('e-rara:8562848');
  assert.ok(!describeDocument({ selected: single.id, sheet: 7 }, { record: single }).title.includes('Blatt'));
});

test('a search names the query and the size of the result list', () => {
  assert.equal(
    describeDocument({ q: 'Siegfriedkarte' }, { count: 4 }).title,
    '„Siegfriedkarte“ · 4 Karten · Kartenzeit',
  );
  assert.equal(describeDocument({ q: 'Dufour' }, { count: 1 }).title, '„Dufour“ · 1 Karte · Kartenzeit');
  // Before the list reports its size the count is simply left out, never "0".
  const early = describeDocument({ q: 'Dufour' }, {}).title;
  assert.equal(early, '„Dufour“ · Kartenzeit');
  assert.match(describeDocument({ q: 'Dufour' }, { count: 3 }).description, /^3 Karten: Historische Karten zu „Dufour“ auf der Karte suchen/);
});

test('a chosen place names the title when no query was typed', () => {
  assert.equal(describeDocument({ place: 'Zürich (ZH)' }, { count: 150 }).title, '„Zürich (ZH)“ · 150 Karten · Kartenzeit');
  // The typed query wins over the place it produced.
  assert.equal(describeDocument({ q: 'Winterthur', place: 'Winterthur (ZH)' }, { count: 2 }).title, '„Winterthur“ · 2 Karten · Kartenzeit');
});

test('a collection filter names the collection', () => {
  const collection = 'Pläne aus Zürich (Stadt und Umgebung)';
  const { title, description } = describeDocument({ collection }, { count: 47 });
  assert.equal(title, `Sammlung „${collection}“ · 47 Karten · Kartenzeit`);
  assert.match(description, /^47 aus der Sammlung „Pläne aus Zürich \(Stadt und Umgebung\)“/);
  // Without a known count the sentence still reads correctly.
  assert.match(describeDocument({ collection }, {}).description, /^Historische Karten aus der Sammlung/);
});

test('a selected record wins over every filter', () => {
  const record = recordOf('e-rara:8562848');
  const { title } = describeDocument({ selected: record.id, q: 'Dufour', collection: 'X' }, { record, count: 9 });
  assert.equal(title, 'Das Zürychgow (1547) · Kartenzeit');
});

test('queries are collapsed, capped and never mistaken for markup', () => {
  assert.equal(describeDocument({ q: '  Wild\n\tkarte  ' }, { count: 3 }).title, '„Wild karte“ · 3 Karten · Kartenzeit');
  const long = describeDocument({ q: 'a'.repeat(200) }, {}).title;
  assert.ok(long.length < 80, `title stays readable: ${long}`);
  assert.ok(long.includes('…'));
  // The title is text, not HTML: the angle brackets arrive as typed.
  const hostile = describeDocument({ q: '<script>alert(1)</script>' }, {}).title;
  assert.ok(hostile.includes('<script>'), hostile);
  assert.ok(!hostile.includes('&lt;'));
  for (const state of [{}, { q: '' }, { place: '' }, { collection: '' }, { selected: '' }]) {
    const { title, description } = describeDocument(state, {});
    assert.ok(!/undefined|null|NaN/.test(title), `no developer text in “${title}”`);
    assert.ok(!/undefined|null|NaN/.test(description), `no developer text in “${description}”`);
    assert.ok(!/\s{2,}/.test(title), `no double spaces in “${title}”`);
  }
});

test('long record titles are cut at a word boundary, not inside a word', () => {
  const record = {
    id: 'x:2',
    title: 'Geographische oder grund-richtige Verzeichnus der schönen Situation der Statt Zürich, ihres Sees und derselbigen umligenden Landschaft',
    yearStart: 1692,
    yearEnd: 1692,
    institution: 'Zentralbibliothek Zürich',
  };
  const { title } = describeDocument({ selected: record.id }, { record });
  const shortened = title.replace(' (1692) · Kartenzeit', '');
  assert.ok(shortened.endsWith('…'), title);
  assert.ok(!/\s…/.test(shortened), title);
  assert.ok(shortened.length <= 72, String(shortened.length));
  // The last visible word is complete: the next character in the source is a space.
  const head = shortened.slice(0, -1);
  assert.ok(record.title.startsWith(head), head);
  assert.equal(record.title[head.length], ' ');
});

test('shortenText keeps short text untouched and drops pure whitespace', () => {
  assert.equal(shortenText('Dufourkarte', 48), 'Dufourkarte');
  assert.equal(shortenText('   ', 48), '');
  assert.equal(shortenText(null, 48), '');
  assert.equal(shortenText('a b c d e f g h i j', 10), 'a b c d e…');
});

