      collectionTitle = await cdp.waitFor(
        `(() => {
          const rows = document.querySelectorAll('#result-list > *').length;
          const match = /^Sammlung „([^”]*)“ · (\\d+) Karten · Kartenzeit$/.exec(document.title);
          if (!match || rows < 1 || Number(match[2]) !== rows) return '';
          return { title: document.title, rows };
        })()`,
        { label: 'collection named in the tab', timeout: 12_000 },
      );
    } catch {
