function close() {
  if (panel.hidden) return;
  viewer?.destroy();
  viewer = null;
  stripObserver?.disconnect();
  stripObserver = null;
  page = 0;
  panel.hidden = true;
  if (scrim) scrim.hidden = true;
  panel.setAttribute('aria-modal', 'false');
  document.body.classList.remove('has-detail');
  // A closed panel must not keep naming a record, or a sheet number, or a
  // viewer region in the shared URL: after “Schliessen (Esc)” a reload shows
  // the list again, the browser tab (title.js) goes back to the search, and a
  // copied link no longer reopens the record the visitor just closed. The
  // write replaces the current entry instead of opening one — closing is not a
  // navigation step of its own, so “back” still walks the exploration (D6).
  // The panel is hidden *before* this write, because clearing `selected`
  // notifies the subscribers synchronously and the store subscription below
  // would otherwise call close() again.
  const state = ctx.store.getState();
  if (state.selected || state.sheet !== 1 || state.vv) {
    ctx.store.update({ selected: '', sheet: 1, vv: '' }, { history: 'replace' });
  }
  current = null;
  body.replaceChildren();
  opener?.focus?.();
  opener = null;
  ctx.bus.emit('record:deselected', {});
}

