  // Focus the heading only when the panel opens (not when its content is swapped).
  if (!wasOpen) body.querySelector('[data-detail-heading]')?.focus();
  // The viewer loads its manifest for every entry point, including `?sel=` links.
  loadManifest(record);
  // The panel is what a visitor sees; `selected` in the store outlives it (the
  // address keeps naming the record, and the sidebar's “Für den Vergleich
  // merken” pins it), so the panel announces its own visibility for the
  // document title (title.js) and for anything else that cares about the
  // overlay rather than the state.
  ctx.bus.emit('detail:open', { record });
}

function close() {
  if (panel.hidden) return;
  viewer?.destroy();
  viewer = null;
  stripObserver?.disconnect();
  stripObserver = null;
  page = 0;
  const closedRecord = current?.id ?? null;
  panel.hidden = true;
  if (scrim) scrim.hidden = true;
  panel.setAttribute('aria-modal', 'false');
  document.body.classList.remove('has-detail');
  // A closed panel must not leave a sheet number or a viewer region behind in
  // the shared URL. `selected` deliberately stays: the address keeps naming
  // the record the visitor was reading — that link opens the panel again, and
  // the sidebar's “Für den Vergleich merken” works on the record that is still
  // selected. What the visitor *sees* is the list, and the document title
  // follows that through `detail:closed` below.
  if (ctx.store.getState().sheet !== 1 || ctx.store.getState().vv) ctx.store.update({ sheet: 1, vv: '' });

