let count = null;
let applied = null;
/**
 * The record the *panel* shows — not simply the store's `selected`: a closed
 * panel keeps its record selected (the address stays shareable and the
 * sidebar's compare pin works on it), but the page the visitor sees is the
 * result list. detail.js announces the overlay with `detail:open` /
 * `detail:closed`; on start-up a `?sel=` deep link opens the panel while both
 * modules initialise, so the store's selection is the honest starting value.
 */
let openRecordId = ctx.store.getState().selected && ctx.data.recordIndex?.has(ctx.store.getState().selected) ? ctx.store.getState().selected : null;

function apply() {
  const state = ctx.store.getState();
  const record = openRecordId ? (ctx.data.recordIndex?.get(openRecordId) ?? null) : null;
  const next = describeDocument(state, { record, count, base, baseDescription });

