  openRecordId = record?.id ?? null;
  apply();
});
ctx.bus.on('detail:closed', () => {
  openRecordId = null;
  apply();
});
ctx.bus.on('records:filtered', ({ records } = {}) => {
  count = Array.isArray(records) ? records.length : null;
  apply();
});
apply();

