await cdp.click('#viewer-stage');

// While the panel is open the address names the record — that is the link a
// visitor copies (or the panel's own “Permalink kopieren”).
const openSearch = await cdp.eval(`location.search`);
check('a record that is open is named in the address', /(?:^|[?&])sel=/.test(openSearch), openSearch);
await cdp.pressKey('Escape');
const closed = await cdp.eval(`document.querySelector('#detail')?.hidden`);
check('Escape closes the detail panel', closed === true);
// Closing is a dismissal, not a navigation: the region of the closed sheet
// goes, but the record stays named in the address (that link reopens the
// panel, and the sidebar's compare pin works on the record that is still
// selected). What the visitor sees is the list — the document title follows
// the panel, not the address, and section 8l checks exactly that.
const closedSearch = await cdp.eval(`location.search`);
check('closing the panel clears the region from the address', !/(?:^|[?&])vv=/.test(closedSearch), `${openSearch} -> ${closedSearch}`);
check('a closed panel keeps the record shareable in the address', /(?:^|[?&])sel=/.test(closedSearch), closedSearch);

